out = []
for k, (ts, bs) in T.items():
    assert len(ts) == 10 and len(bs) == 10, k
    for i, t in enumerate(ts):
        for j, b in enumerate(bs):
            out.append({'t': t[0], 'b': b[0], 'et': t[1], 'eb': b[1], 'k': k})
random.Random(7).shuffle(out)
assert len(out) == 1000 and len({(x['t'], x['b']) for x in out}) == 1000
assert all(len(x['t']) <= 80 and len(x['b']) <= 200 and len(x['et']) <= 80 and len(x['eb']) <= 200 for x in out)
json.dump(out, open('data/bot/push.json', 'w'), ensure_ascii=False, separators=(',', ':'))
print(len(out))
